# rotate panel positions counterclockwise, preserving each 5x5 panel's internal orientation
src={(0,0):panels[0],(0,1):panels[1],(1,0):panels[2],(1,1):panels[3]}
# source (i,j) -> destination (1-j,i)
dest={(1-j,i):p for (i,j),p in src.items()}
out2=[]
for i in range(2):
    for ri in range(5):
        row=[]
        for j in range(2):
            row+=dest[(i,j)][ri]
            if j==0: row.append(6)
        out2.append(row)
    if i==0: out2.append([6]*11)
print('\n'.join(' '.join(map(str,r)) for r in out2))
print(len(out2),set(map(len,out2)))

